// Batch approval with audit logging and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"sort"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Build request hash: "bulk-approve.v3\n" + sorted "<len>:<ID>" concatenated
		sortedIDs := make([]string, len(ids))
		copy(sortedIDs, ids)
		sort.Strings(sortedIDs)

		hashInput := "bulk-approve.v3\n"
		for _, id := range sortedIDs {
			hashInput += fmt.Sprintf("%d:%s", len(id), id)
		}

		hash := sha256.Sum256([]byte(hashInput))
		requestHash := hex.EncodeToString(hash[:])

		// Build response JSON for ActionRequest
		response := fmt.Sprintf(`{"approvedIds":[%s]}`, strings.Join(sortedIDs, ","))
		for i := range sortedIDs {
			response = fmt.Sprintf(`{"approvedIds":[%s]}`, strings.Join(sortedIDs, `","`))
			response = strings.ReplaceAll(response, `","`, `", "`)
			response = `{"approvedIds":["` + strings.Join(sortedIDs, `","`) + `"]}`
		}

		// Rebuild properly
		response = `{"approvedIds":[`
		for i, id := range sortedIDs {
			if i > 0 {
				response += ","
			}
			response += `"` + id + `"`
		}
		response += `]}`

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check for existing action request (idempotency check)
		var existingResponse string
		var existingApprovedIDs []string
		err = tx.QueryRow(ctx, 
			`SELECT response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, 
			u.Tenant, u.User, "bulk-approve.v3", key).Scan(&existingResponse)

		if err == nil {
			// Found existing - this is a replay
			// Parse response to get approved IDs
			var existingResult protocol.Result
			if err := pgx.ScanJSON(&existingResult, []byte(existingResponse)); err == nil {
				existingApprovedIDs = existingResult.ApprovedIDs
				// Check if same set of IDs
				if len(existingApprovedIDs) == len(ids) {
					same := true
					for i := range ids {
						if existingApprovedIDs[i] != ids[i] {
							same = false
							break
						}
					}
					if same {
						return existingResult, true, nil
					}
				}
			}
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// Lock purchases for update
		rows, err := tx.Query(ctx, 
			`SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, 
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// If any target is invalid (missing, not submitted, or created by actor), reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update purchases
		tag, err := tx.Exec(ctx, 
			`UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, 
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Insert ActionRequest first
		_, err = tx.Exec(ctx,
			`INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6)`,
			u.Tenant, u.User, "bulk-approve.v3", key, requestHash, response)
		if err != nil {
			// If unique constraint violation, another transaction won
			if pgxErr, ok := err.(*pgx.PgError); ok && pgxErr.Code == "23505" {
				// Rollback to check what happened
				if rollbackErr := tx.Rollback(ctx); rollbackErr != nil {
					return protocol.Result{}, false, rollbackErr
				}
				// Retry the idempotency check path
				var retryResponse string
				if retryErr := pool.QueryRow(ctx,
					`SELECT response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
					u.Tenant, u.User, "bulk-approve.v3", key).Scan(&retryResponse); retryErr == nil {
					var retryResult protocol.Result
					if scanErr := pgx.ScanJSON(&retryResult, []byte(retryResponse)); scanErr == nil {
						return retryResult, true, nil
					}
				}
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			return protocol.Result{}, false, err
		}

		// Insert ApprovalAudit for each approved purchase
		for _, id := range ids {
			_, err = tx.Exec(ctx,
				`INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus") VALUES ($1,$2,$3,$4,$5,$6,$7)`,
				u.Tenant, id, u.User, "bulk-approve.v3", key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: ids}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

